const won=n=>{if(n===null||n===undefined||n==='')return '원문 확인';const e=Number(n)/100000000;if(!Number.isFinite(e))return '원문 확인';return `${Number.isInteger(e)?e:e.toFixed(2)}억`};
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const normalizeSearch=value=>String(value||'').toLowerCase().replace(/\s+/g,'');
const load=()=>{try{const saved=JSON.parse(localStorage.getItem('properties')||'null');if(!Array.isArray(saved))return [...seedProperties];if(localStorage.getItem('propertyDataVersion')===PROPERTY_DATA_VERSION)return saved;const custom=saved.filter(p=>!legacySeedIds.has(p.id)&&!String(p.id||'').startsWith('BLOG-'));const migrated=[...seedProperties,...custom.filter(p=>!seedProperties.some(seed=>seed.id===p.id))];localStorage.setItem('propertyDataVersion',PROPERTY_DATA_VERSION);localStorage.setItem('properties',JSON.stringify(migrated));return migrated}catch{return [...seedProperties]}};
