const getDataConfig=()=>{let saved={};try{saved=JSON.parse(localStorage.getItem('dataConfig')||'{}')}catch{}return {...window.DATA_CONFIG,...saved,kakaoChatUrl:saved.kakaoChatUrl||window.DATA_CONFIG.kakaoChatUrl}};
const normalizeKakaoUrl=value=>{const url=String(value||'').trim();if(!url)return '';if(/^https:\/\//i.test(url))return url;const id=url.replace(/^@/,'');return `https://pf.kakao.com/${id}/chat`};
const getKakaoUrl=()=>normalizeKakaoUrl(getDataConfig().kakaoChatUrl);
const maskPublicAddress=value=>String(value||'').replace(/(\d+)(?:-\d+)?$/,(_,main)=>`${main}번지 일대`);
