const advertisingOf=p=>({reviewStatus:'needs_review',propertyType:'재개발 조합원입주권',transactionType:'매매',location:'',areaSqm:null,floor:'',totalFloors:'',approvalDate:'',direction:'',directionBasis:'',rooms:null,bathrooms:null,moveInDate:'',parking:'',managementFee:null,managementFeeDetails:'',...(p.advertising||{})});
const hasAdValue=value=>value!==null&&value!==undefined&&String(value).trim()!=='';
const adDisplay=(value,suffix='')=>hasAdValue(value)?`${escapeHtml(value)}${suffix}`:'<span class="ad-missing">확인 필요</span>';
const advertisingMissing=p=>{const ad=advertisingOf(p),missing=[];[['소재지','location'],['면적','areaSqm'],['중개대상물 종류','propertyType'],['거래형태','transactionType'],['해당 층','floor'],['총 층수','totalFloors'],['사용승인일','approvalDate'],['방향','direction'],['방향 기준','directionBasis'],['방 수','rooms'],['욕실 수','bathrooms'],['입주 가능일','moveInDate'],['주차대수','parking'],['관리비','managementFee'],['관리비 내역','managementFeeDetails']].forEach(([label,key])=>{if(!hasAdValue(ad[key]))missing.push(label)});if(!hasAdValue(p.sale))missing.push('가격');return missing};
const advertisingVerified=p=>advertisingOf(p).reviewStatus==='verified'&&advertisingMissing(p).length===0;
const isPublicListing=p=>p.public===true&&advertisingVerified(p)&&!p.needsReview;
function propertyImage(p,detailView=false){const cover=Array.isArray(p.media)?p.media.find(item=>item?.type==='image'&&item?.role==='cover')||p.media.find(item=>item?.type==='image'):null,imageUrl=cover?.url||p.imageUrl;if(!imageUrl)return '';const alt=escapeHtml(cover?.alt||p.imageAlt||`${p.area} ${p.unit} 입주권 대표 이미지`);return `<img class="${detailView?'detail-property-photo':'property-photo'}" src="${escapeHtml(imageUrl)}" alt="${alt}" ${detailView?'':'loading="lazy"'} onerror="this.parentElement.classList.add('image-fallback');this.remove()">`}
function card(p){const adVerified=advertisingVerified(p);return `<article class="property-card" tabindex="0" role="link" onclick="location.hash='#/property/${p.id}'" onkeydown="if(event.key==='Enter')location.hash='#/property/${p.id}'"><div class="property-img">${propertyImage(p)}<div class="badges">${p.source==='네이버 블로그'?'<span class="badge blog">블로그 확인매물</span>':p.inventory==='owned'?'<span class="badge">보유매물</span>':''}${p.featured?'<span class="badge featured">추천</span>':''}${p.needsReview?'<span class="badge review">재확인</span>':''}${adVerified?'<span class="badge ad-ok">광고정보 확인</span>':'<span class="badge ad-review">광고정보 검수 중</span>'}</div></div><div class="property-body"><h3>${p.area}<br>${p.unit} 입주권</h3><div class="price-main"><span>매매가</span><strong>${won(p.sale)}</strong></div><div class="price-row"><span>초기투자금</span><strong>${won(p.initial)}</strong></div><div class="price-row"><span>총 예상 매수가</span><strong>${won(p.total)}</strong></div><div class="verified"><strong>${statusText[p.status]||p.status}</strong><br>${p.verificationLabel||`최근 확인 ${p.verified||'-'}`}<br>${p.listedAt?`등록일 ${p.listedAt}`:''}</div></div></article>`}
const shelf=(items)=>`<div class="shelf">${items.map(card).join('')}</div>`;
const normalizeTransaction=(row,region)=>({
 region:row.region||row.area_group||region,
 area:row.area||row.area_name||row.district||row.구역||'구역 확인중',
 contractDate:row.contractDate||row.contract_date||row.date||row.계약일||'',
 propertyType:row.propertyType||row.property_type||row.type||row.유형||'실거래',
 address:row.address||row.lot_address||row.주소||'',
 building:row.building||row.building_name||row.건물명||'',
 areaSqm:Number(row.areaSqm||row.area_sqm||row.exclusive_area||row.면적||0),
 floor:row.floor||row.층||'-',
 price:Number(row.price||row.deal_amount||row.transaction_price||row.거래금액||0),
 source:row.source||'GitHub 자동수집'
});
async function loadBundledTransactions(){const cfg=getDataConfig();try{const res=await fetch(cfg.bundledSangdoUrl||'assets/sangdo15-transactions-public.json');if(!res.ok)throw new Error(res.status);const json=await res.json();const sangdo=(json.transactions||[]).map(x=>normalizeTransaction(x,'상도 신속통합기획'));transactions=[...fallbackTransactions.filter(x=>x.region==='노량진뉴타운'),...sangdo].sort((a,b)=>b.contractDate.localeCompare(a.contractDate));return true}catch{return false}}
let propertySyncMeta={asOf:'2026-08-20',count:seedProperties.filter(p=>p.region==='노량진뉴타운').length,sourceName:'내가 찾던 부동산 네이버 블로그'};
async function loadBundledProperties(){const cfg=getDataConfig();try{const res=await fetch(cfg.bundledNoryangjinPropertiesUrl||'assets/noryangjin-blog-properties.json');if(!res.ok)throw new Error(res.status);const json=await res.json();const rows=Array.isArray(json)?json:(json.properties||[]);if(!rows.length)throw new Error('매물 없음');const localById=new Map(properties.map(p=>[p.id,p]));const blogRows=rows.map(row=>{const local=localById.get(row.id);return local?.manualStatus?{...row,status:local.status,soldAt:local.soldAt,manualStatus:true}:row}).sort((a,b)=>String(b.listedAt||'').localeCompare(String(a.listedAt||'')));const custom=properties.filter(p=>p.source!=='네이버 블로그'&&!String(p.id||'').startsWith('BLOG-'));properties=[...blogRows,...custom.filter(p=>!blogRows.some(row=>row.id===p.id))];propertySyncMeta={asOf:json.source?.asOf||'',count:blogRows.length,sourceName:json.source?.name||'내가 찾던 부동산 네이버 블로그',notice:json.source?.notice||''};localStorage.setItem('propertyDataVersion',PROPERTY_DATA_VERSION);save();return true}catch{return false}}
let progressData={source:{name:'노량진뉴타운 진행상황',url:'https://blog.naver.com/partir_12/224379767305',asOf:'2026-08-15',notice:'조합 일정과 행정 절차에 따라 변경될 수 있습니다.'},stages:['관리처분','이주','철거','착공','일반분양·본공사','입주'],areas:[]};
async function loadBundledProgress(){const cfg=getDataConfig();try{const res=await fetch(cfg.bundledNoryangjinProgressUrl||'assets/noryangjin-progress.json');if(!res.ok)throw new Error(res.status);const json=await res.json();if(!Array.isArray(json.areas)||!json.areas.length)throw new Error('진행상황 없음');progressData=json;return true}catch{return false}}
async function loadRemoteTransactions(){const cfg=getDataConfig(),sources=[[cfg.noryangjinTransactionsUrl,'노량진뉴타운'],[cfg.sangdoTransactionsUrl,'상도 신속통합기획']].filter(x=>x[0]);if(!sources.length){const count=transactions.filter(x=>x.region==='상도 신속통합기획').length;return {ok:true,message:`sangdo15 공개용 실거래 ${count}건 · 주소 마스킹 · 기준일 2026-08-19`}}try{const batches=await Promise.all(sources.map(async([url,region])=>{const res=await fetch(`${url}${url.includes('?')?'&':'?'}t=${Date.now()}`);if(!res.ok)throw new Error(`${res.status}`);const json=await res.json();const rows=Array.isArray(json)?json:(json.transactions||json.data||[]);return rows.map(x=>normalizeTransaction(x,region))}));const remoteRegions=new Set(batches.flat().map(x=>x.region));transactions=[...transactions.filter(x=>!remoteRegions.has(x.region)),...batches.flat()].sort((a,b)=>b.contractDate.localeCompare(a.contractDate));return {ok:true,message:`GitHub에서 ${batches.flat().length}건을 동기화했습니다.`}}catch(e){return {ok:false,message:`GitHub 동기화 실패(${e.message}) · 마지막 정상 데이터를 유지합니다.`}}}
function transactionRows(items){return `<div class="transaction-scroll"><table class="transaction-table"><thead><tr><th>계약일</th><th>권역·구역</th><th>주소</th><th>유형</th><th>면적</th><th>거래금액</th></tr></thead><tbody>${items.map(t=>`<tr><td>${t.contractDate}</td><td><strong>${t.area}</strong><br><small class="muted">${t.region}</small></td><td>${maskPublicAddress(t.address)||'-'}<br><small class="muted">상세 주소 비공개</small></td><td>${t.propertyType}</td><td>${t.areaSqm?t.areaSqm.toFixed(1)+'㎡':'-'}</td><td><strong>${won(t.price)}</strong></td></tr>`).join('')}</tbody></table></div>`}
function transactionsPage(){return `<div class="page-hero"><p class="eyebrow">Verified Transaction Data</p><h1>동작구 재개발<br>실거래내역</h1><p>노량진뉴타운과 상도 신속통합기획 구역의 신고된 거래 흐름을 확인합니다.</p></div><section class="section" style="padding-top:20px"><div id="syncState" class="sync-box"><span class="data-source">데이터 확인 중</span></div><div class="premium-request"><div><p class="eyebrow">Noryangjin Premium Reference</p><h2>노량진뉴타운 구역별<br>프리미엄이 궁금하신가요?</h2><p>공개 실거래 신고자료만으로는 입주권의 구역별 프리미엄을 정확히 분리하기 어렵습니다. 내가 찾던 부동산은 구역별 프리미엄 참고자료를 별도로 보유하고 있으며, 궁금한 구역을 요청하시면 확인 가능한 범위에서 안내해 드립니다.</p><small>프리미엄은 권리가액·예상 분담금·대출 승계와 개별 거래조건에 따라 달라질 수 있습니다.</small></div><a class="btn secondary" href="#/contact">구역별 프리미엄 문의</a></div><div class="market-tabs"><button class="active" data-region="">전체</button><button data-region="노량진뉴타운">노량진뉴타운</button><button data-region="상도 신속통합기획">상도 신속통합기획</button></div><div id="transactionResults">${transactionRows(transactions)}</div><p class="muted">실거래 신고 시차와 정정·해제 신고로 최근 데이터는 변경될 수 있습니다. 개별 거래 판단 전 원문을 확인하세요.</p></section>`}
function renderTransactionFilter(region=''){const list=transactions.filter(t=>!region||t.region===region);const target=document.querySelector('#transactionResults');if(target)target.innerHTML=transactionRows(list)}
function progressCard(item){const live=properties.filter(p=>p.area===item.area&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)).length,sold=properties.filter(p=>p.area===item.area&&p.status==='sold').length;return `<article class="progress-card"><div class="progress-card-head"><div><span class="phase-chip ${item.phaseGroup}">${item.phaseGroup}</span><h2>${item.area}</h2></div><strong>${item.headline}</strong></div><p>${item.detail}</p><div class="progress-line" aria-label="${item.area} 사업 진행단계">${progressData.stages.map((stage,index)=>`<div class="progress-step ${index<item.stageIndex?'done':index===item.stageIndex?'current':''}"><i></i><span>${stage}</span></div>`).join('')}</div><div class="progress-facts"><div><small>현재 일정</small><strong>${item.schedule}</strong></div><div><small>84㎡ 조합원분양가</small><strong>${item.memberPrice84}</strong></div><div><small>다음 확인사항</small><strong>${item.nextStep}</strong></div></div><div class="progress-card-foot"><div>${item.checkpoints.map(point=>`<span>${point}</span>`).join('')}</div><a class="text-link" href="#/market-status">매물 현황 ${live}건 · 완료 ${sold}건 →</a></div></article>`}
function progressCards(items){return items.length?`<div class="progress-list">${items.map(progressCard).join('')}</div>`:'<div class="panel">해당 단계의 구역이 없습니다.</div>'}
function progressPage(){const counts=progressData.areas.reduce((acc,item)=>(acc[item.phaseGroup]=(acc[item.phaseGroup]||0)+1,acc),{});return `<div class="page-hero"><p class="eyebrow">Noryangjin Project Progress</p><h1>노량진 1~8구역<br>사업 진행상황</h1><p>관리처분 이후 이주·철거·착공·본공사까지, 각 구역이 지금 어디에 있는지 비교합니다.</p></div><section class="section progress-section" style="padding-top:20px"><div class="progress-source"><div><p class="eyebrow">Updated ${progressData.source.asOf}</p><h2>구역별 진행단계 한눈에 보기</h2><p>${progressData.source.notice}</p></div><a class="btn secondary" href="${progressData.source.url}" target="_blank" rel="noopener">진행상황 원문 ↗</a></div><div class="progress-summary"><button class="active" data-progress-group=""><span>전체</span><strong>${progressData.areas.length}</strong></button>${['이주','철거','공사'].map(group=>`<button data-progress-group="${group}"><span>${group} 단계</span><strong>${counts[group]||0}</strong></button>`).join('')}</div><div id="progressResults">${progressCards(progressData.areas)}</div><div class="notice progress-notice">진행상황은 ${progressData.source.asOf} 기준입니다. 정비사업 일정은 조합 의결, 인허가와 공사 여건에 따라 달라질 수 있으므로 중요한 의사결정 전 조합·관할기관의 최신 공고를 확인해 주세요.</div></section>`}
function renderProgressFilter(group=''){const target=document.querySelector('#progressResults');if(target)target.innerHTML=progressCards(progressData.areas.filter(item=>!group||item.phaseGroup===group))}
function marketStatus(){const cfg=getDataConfig(),noryAreas=[1,2,3,4,5,6,7,8].map(n=>`노량진${n}구역`);return `<div class="page-hero"><p class="eyebrow">Noryangjin Market Board</p><h1>노량진뉴타운<br>구역별 거래현황</h1><p>내가 찾던 부동산 블로그의 구역별 확인매물을 기준으로 거래가능·거래완료 상태를 관리합니다.</p></div><section class="section" style="padding-top:20px"><div class="blog-source-panel"><div><p class="eyebrow">Official Listing Source</p><h2>네이버 블로그 확인매물 기준</h2><p>${propertySyncMeta.notice||'게시글 등록일과 확인 주차를 함께 표시하며 계약 전 최신 상태를 다시 확인합니다.'}</p><span>기준일 ${propertySyncMeta.asOf||'-'} · 블로그 매물 ${propertySyncMeta.count}건</span></div><a class="btn secondary" href="${cfg.noryangjinBlogUrl}" target="_blank" rel="noopener">전체 블로그 보기 ↗</a></div><div class="area-grid">${noryAreas.map((a,i)=>{const available=properties.filter(p=>p.area===a&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)).length,sold=properties.filter(p=>p.area===a&&p.status==='sold').length;return `<a class="area-tile" href="#/market-status/${encodeURIComponent(a)}"><b>0${i+1}</b><h3>${a}</h3><p>거래가능 ${available} · 거래완료 ${sold}</p></a>`}).join('')}</div><div class="status-grid" style="margin-top:50px"><div class="status-column"><h2>거래가능</h2>${statusRows(properties.filter(p=>p.region==='노량진뉴타운'&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)))}</div><div class="status-column"><h2>거래완료</h2>${statusRows(properties.filter(p=>p.region==='노량진뉴타운'&&p.status==='sold'),true)}</div></div></section>`}
function statusRows(items,sold=false){return `<div class="status-list">${items.length?items.map(p=>`<div class="status-row"><div><strong>${p.area} · ${p.unit}</strong><small>매매가 ${won(p.sale)} · 등록 ${p.listedAt||'-'}</small><small>${p.verificationLabel||`최근 확인 ${p.verified||'-'}`}</small>${p.dataNote?`<small class="status-note">${p.dataNote}</small>`:''}${p.blogUrl?`<a class="blog-link" href="${p.blogUrl}" target="_blank" rel="noopener">블로그 원문 보기 ↗</a>`:''}</div><span class="${sold?'sold-mark':''}">${statusText[p.status]}</span></div>`).join(''):'<div class="status-row">등록된 매물이 없습니다.</div>'}</div>`}
function homeSearchEntries(){const live=properties.filter(p=>isPublicListing(p)&&!['sold','hidden'].includes(p.status));return [{category:'통합 안내',title:'재개발 구역별 정보',summary:'노량진 1~8구역과 상도 신속통합기획을 비교합니다.',url:'#/areas',keywords:'재개발 구역 정보 노량진 상도'},{category:'매물 검색',title:'내 예산으로 매물 찾기',summary:'초기투자금·총 예상 매수가·평형으로 검색합니다.',url:'#/search',keywords:'현재 매물 검색 초기투자금 총매수가 예산 평형'},{category:'거래 데이터',title:'노량진·상도 실거래내역',summary:'공개 실거래 흐름과 구역별 프리미엄 상담을 확인합니다.',url:'#/transactions',keywords:'실거래 프리미엄 거래 가격'},{category:'현장 분석',title:'김소장의 분석',summary:'블로그에 정리한 매물·구역·시장 분석을 봅니다.',url:'#/insights',keywords:'김소장 분석 블로그 시장'}].concat(progressData.areas.map(item=>({category:'구역 정보',title:item.area,summary:`${item.phaseGroup} · ${item.headline}`,url:'#/progress',keywords:`${item.area} ${item.phaseGroup} ${item.headline} ${item.detail}`})),live.map(item=>({category:'블로그 확인매물',title:`${item.area} ${item.unit} 입주권`,summary:`초기투자금 ${won(item.initial)} · 총매수가 ${won(item.total)}`,url:`#/property/${item.id}`,keywords:`${item.area} ${item.region} ${item.unit} 현재 매물 입주권 초기투자금 총매수가`})))}
function runHomeSearch(valueOrEvent){if(valueOrEvent&&typeof valueOrEvent.preventDefault==='function')valueOrEvent.preventDefault();const field=document.querySelector('#homeSearchInput'),target=document.querySelector('#homeSearchResults');if(!field||!target)return;if(typeof valueOrEvent==='string')field.value=valueOrEvent;const raw=String(field.value||'').trim(),query=normalizeSearch(raw),items=homeSearchEntries().filter(item=>!query||normalizeSearch(`${item.title} ${item.summary} ${item.keywords}`).includes(query)).slice(0,6);target.innerHTML=items.length?`<div class="home-search-result-head"><strong>${raw?`‘${escapeHtml(raw)}’ 검색결과`:'추천 재개발 정보'}</strong><span>${items.length}건</span></div><div class="home-search-result-list">${items.map(item=>`<a href="${item.url}"><small>${item.category}</small><strong>${item.title}</strong><span>${item.summary}</span></a>`).join('')}</div>`:`<div class="home-search-empty"><strong>바로 찾지 못했습니다.</strong><span>구역명이나 ‘매물’, ‘실거래’, ‘프리미엄’을 입력하거나 안내봇에 질문해 주세요.</span><button type="button" onclick="toggleChatbot(true)">김소장 안내봇 열기</button></div>`}
function home(){const live=properties.filter(p=>isPublicListing(p)&&!['sold','hidden'].includes(p.status));return `<section class="hero home-search-hero"><div class="hero-image"><div class="hero-copy"><p class="eyebrow">2026 August · Dongjak Redevelopment</p><h1>찾고 싶은 재개발 정보,<br>여기서 바로 검색하세요.</h1><p>구역 진행상황, 현재 매물, 실거래와 김소장의 분석을 한 번에 찾습니다.</p><div class="home-search-box"><form id="homeSearchForm"><label for="homeSearchInput">재개발 정보 검색</label><div class="home-search-row"><input id="homeSearchInput" type="search" autocomplete="off" placeholder="예: 노량진7구역, 초기투자금, 상도15구역"><button type="submit">검색</button></div><div class="home-search-quick"><span>빠른 검색</span><button type="button" data-home-query="노량진7구역">7구역</button><button type="button" data-home-query="현재 매물">현재 매물</button><button type="button" data-home-query="실거래">실거래</button><button type="button" data-home-query="김소장 분석">김소장 분석</button></div></form><div id="homeSearchResults" class="home-search-results" aria-live="polite"></div></div><div class="actions"><a class="btn light" href="#/areas">구역별 정보</a><a class="btn secondary" style="color:white;border-color:white" href="#/search">내 예산으로 찾기</a></div></div></div></section>
<section class="section"><div class="editorial-grid"><a class="editorial-card" href="#/area/noryangjin"><div class="visual"></div><h3>노량진뉴타운</h3><p class="muted">1~8구역의 사업단계와 실제 매물의 초투·총매수가를 비교합니다.</p><span class="text-link">노량진 전체보기 →</span></a><a class="editorial-card" href="#/area/sangdo"><div class="visual"></div><h3>상도 신속통합기획</h3><p class="muted">상도14·15구역을 시작으로 신속통합기획 사업지를 추적합니다.</p><span class="text-link">상도 전체보기 →</span></a></div></section>
<section class="section"><div class="section-head"><div><h2>이번 주 블로그 확인매물</h2><p class="muted">내가 찾던 부동산 블로그에 등록하고 최근 상태를 확인한 매물입니다.</p></div><a class="text-link" href="#/market-status">구역별 현황 →</a></div>${shelf(live.filter(p=>p.featured))}</section>
<section class="section"><div class="banner"><div><p class="eyebrow">Budget Finder</p><h2>내 자금으로 가능한 매물이 궁금하신가요?</h2><p>현금·총매수가·평형을 입력하면 조건에 맞는 매물을 찾아드립니다.</p></div><a class="btn light" href="#/search">내 예산으로 매물 찾기</a></div></section>
<section class="section"><div class="story"><div class="story-img"></div><div class="story-copy"><p class="eyebrow">구역분석 · 노량진7구역</p><h2>사업 후반부,<br>이제는 총매수가를<br>비교할 시점</h2><p class="muted">최근 매물 공백, 분양가, 총매수가 관점에서 현재 시장을 정리합니다.</p><a class="text-link" href="#/area/noryangjin">7구역 분석 보기 →</a></div></div></section>
<section class="section"><div class="section-head"><div><h2>총매수가 30억 이하</h2><p class="muted">블로그에 총 예상 매수가가 확인된 매물만 비교합니다.</p></div></div>${shelf(live.filter(p=>Number.isFinite(p.total)&&p.total<=3000000000))}</section>
<section class="section"><div class="section-head"><div><h2>노량진뉴타운</h2><p class="muted">1~8구역의 현재 사업단계와 확인매물을 함께 살펴보세요.</p></div><a class="text-link" href="#/progress">구역별 진행상황 보기 →</a></div><div class="area-grid">${[1,2,3,4,5,6,7,8].map(n=>{const areaName=`노량진${n}구역`,progress=progressData.areas.find(item=>item.area===areaName);return `<a class="area-tile" href="#/progress"><b>0${n}</b><h3>${areaName}</h3><p class="muted">${progress?.headline||'진행상황 확인'}<br>현재 매물 ${live.filter(p=>p.area===areaName).length}</p></a>`}).join('')}</div></section>
<section class="section"><div class="story"><div class="story-copy"><p class="eyebrow">Sangdo Fast-track Planning</p><h2>상도,<br>다음 재개발 흐름을 보다</h2><div class="actions"><a class="btn" href="#/area/sangdo">상도14구역</a><a class="btn secondary" href="#/area/sangdo">상도15구역</a></div></div><div class="story-img"></div></div></section><section class="section"><div class="section-head"><div><h2>거래현황과 실거래</h2><p class="muted">블로그 매물의 현재 상태와 신고된 실거래 흐름을 함께 봅니다.</p></div></div><div class="editorial-grid"><a class="panel" href="#/market-status"><p class="eyebrow">Live Inventory</p><h2>노량진 구역별 거래현황</h2><p>거래가능 ${live.filter(p=>p.region==='노량진뉴타운').length}건 · 거래완료 ${properties.filter(p=>p.region==='노량진뉴타운'&&p.status==='sold').length}건</p><span class="text-link">거래현황 보기 →</span></a><a class="panel" href="#/transactions"><p class="eyebrow">Actual Transactions</p><h2>노량진·상도 실거래내역</h2><p>GitHub 자동수집 데이터와 연결되는 거래 기록입니다.</p><span class="text-link">실거래내역 보기 →</span></a></div></section>${insightBlock()}${consultBlock()}`}
function areasPage(){const nory=progressData.areas.map(item=>({...item,live:properties.filter(p=>p.area===item.area&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)).length,sold:properties.filter(p=>p.area===item.area&&p.status==='sold').length})),sangdo=['상도14구역','상도15구역'].map(area=>({area,deals:transactions.filter(t=>t.area===area).length,live:properties.filter(p=>p.area===area&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)).length}));return `<div class="page-hero areas-hero"><p class="eyebrow">Dongjak Redevelopment Area Guide</p><h1>재개발<br>구역별 정보</h1><p>노량진뉴타운 1~8구역과 상도 신속통합기획을 사업단계, 현재 매물, 실거래 기준으로 탐색합니다.</p></div><section class="section areas-section" style="padding-top:20px"><div class="area-guide-head"><div><p class="eyebrow">Noryangjin New Town</p><h2>노량진뉴타운 1~8구역</h2><p>구역별 진행단계와 블로그 확인매물 현황을 함께 확인하세요.</p></div><div class="area-guide-actions"><a class="btn secondary" href="#/progress">전체 진행상황</a><a class="btn" href="#/market-status">전체 매물현황</a></div></div><div class="area-info-grid">${nory.map((item,index)=>`<article class="area-info-card"><div class="area-info-number">${String(index+1).padStart(2,'0')}</div><span class="phase-chip ${item.phaseGroup}">${item.phaseGroup}</span><h3>${item.area}</h3><strong>${item.headline}</strong><p>${item.detail}</p><div class="area-info-stats"><span>거래가능 <b>${item.live}</b></span><span>거래완료 <b>${item.sold}</b></span></div><small>다음 확인 · ${item.nextStep}</small><div class="area-info-links"><a href="#/progress">진행상황 →</a><a href="#/market-status">매물보기 →</a></div></article>`).join('')}</div></section><section class="section sangdo-area-section"><div class="area-guide-head"><div><p class="eyebrow">Sangdo Fast-track Planning</p><h2>상도 신속통합기획</h2><p>상도14·15구역의 사업 흐름과 공개 실거래를 추적합니다.</p></div><a class="btn secondary" href="#/area/sangdo">상도 전체보기</a></div><div class="sangdo-info-grid">${sangdo.map(item=>`<article><span>신속통합기획 추적</span><h3>${item.area}</h3><p>공개매물 ${item.live}건 · 실거래 ${item.deals}건</p><div><a class="text-link" href="#/area/sangdo">구역정보 →</a><a class="text-link" href="#/transactions">실거래 →</a></div></article>`).join('')}</div></section><section class="area-guide-cta"><p class="eyebrow">Need A Local View?</p><h2>어느 구역이 내 조건에 맞는지<br>김소장에게 물어보세요.</h2><a class="btn light" href="#/contact">구역별 매물 상담</a></section>`}
function landing(){const kakao=getKakaoUrl(),live=properties.filter(p=>p.region==='노량진뉴타운'&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)),featured=live.filter(p=>p.featured).slice(0,4),phaseCounts=progressData.areas.reduce((acc,item)=>(acc[item.phaseGroup]=(acc[item.phaseGroup]||0)+1,acc),{});return `<section class="ad-hero"><div class="ad-hero-copy"><p class="eyebrow">노량진뉴타운 매물 · 재개발 입주권</p><h1>노량진 매물,<br>초기투자금부터<br>총매수가까지.</h1><p>노량진 1~8구역 블로그 확인매물과 사업 진행상황을 모바일에서 빠르게 비교하세요.</p><div class="ad-actions"><a class="btn ad-call" href="tel:02-816-5700" data-conversion="phone">02-816-5700 전화 상담</a>${kakao?`<a class="btn kakao" href="${kakao}" target="_blank" rel="noopener" data-conversion="kakao">카카오로 매물 요청</a>`:''}</div><div class="ad-trust-line"><span>공인중개사 김윤아</span><span>정비사업전문관리사</span><span>등록번호 11590-2025-00024</span></div></div><div class="ad-hero-visual" role="img" aria-label="동작구 노량진뉴타운 재개발 전경"><div><small>현재 블로그 확인매물</small><strong>${live.length}건</strong><span>${propertySyncMeta.asOf} 기준</span></div></div></section><section class="ad-mobile-paths"><a href="#/market-status"><span>01</span><strong>현재 매물</strong><small>구역별 거래가능 현황</small></a><a href="#/progress"><span>02</span><strong>진행상황</strong><small>이주·철거·공사 비교</small></a><a href="#/search"><span>03</span><strong>예산 검색</strong><small>초투·총매수가 기준</small></a></section><section class="section ad-keywords"><div class="section-head"><div><p class="eyebrow">Buyer Decision Guide</p><h2>노량진 재개발 입주권,<br>세 숫자를 함께 봅니다.</h2></div></div><div class="ad-metrics"><article><span>01</span><h3>매매가</h3><p>매도인이 제시한 현재 거래가격을 확인합니다.</p></article><article><span>02</span><h3>초기투자금</h3><p>승계 가능한 이주비대출을 반영해 지금 필요한 현금을 봅니다.</p></article><article><span>03</span><h3>총 예상 매수가</h3><p>예상 분담금까지 더해 신축을 확보하는 전체 비용을 비교합니다.</p></article></div></section><section class="section ad-inventory"><div class="section-head"><div><p class="eyebrow">Naver Blog Verified</p><h2>최근 블로그 확인매물</h2><p class="muted">등록일과 확인 주차, 거래상태를 함께 표시합니다.</p></div><a class="text-link" href="#/market-status">전체 매물 보기 →</a></div>${shelf(featured)}</section><section class="section ad-progress"><div class="section-head"><div><p class="eyebrow">Project Status</p><h2>1~8구역 사업 진행상황</h2></div><a class="text-link" href="#/progress">진행상황 전체보기 →</a></div><div class="ad-phase-grid">${[['이주','이주 준비·진행'],['철거','철거·멸실'],['공사','착공·본공사']].map(([group,label])=>`<a href="#/progress"><strong>${phaseCounts[group]||0}개 구역</strong><span>${label}</span><small>${progressData.areas.filter(item=>item.phaseGroup===group).map(item=>item.area.replace('노량진','')).join(' · ')}</small></a>`).join('')}</div></section><section class="ad-office"><div><p class="eyebrow">Local Redevelopment Office</p><h2>동작구 재개발 현장에서<br>조건을 확인합니다.</h2><p>내가찾던부동산 · 서울특별시 동작구 장승배기로 131, 1층</p><p>대표 김윤아 · 공인중개사 · 정비사업전문관리사</p></div><div class="ad-office-actions"><a href="tel:02-816-5700" data-conversion="phone"><small>대표전화</small><strong>02-816-5700</strong></a><a href="tel:010-7752-9837" data-conversion="mobile"><small>휴대전화</small><strong>010-7752-9837</strong></a></div></section><section class="section ad-faq"><div class="section-head"><h2>상담 전 자주 묻는 질문</h2></div><details><summary>사이트의 매물이 지금도 거래 가능한가요?</summary><p>블로그 등록일과 최근 확인 주차를 표시하지만 상태는 수시로 달라질 수 있습니다. 계약 전 매도 의사와 조건을 다시 확인합니다.</p></details><details><summary>주소와 동·호수가 모두 공개되나요?</summary><p>개인정보와 소유자 요청을 고려해 공개 화면에는 필요한 범위만 표시하고 상세 조건은 상담 과정에서 확인합니다.</p></details><details><summary>초기투자금과 총매수가는 확정 금액인가요?</summary><p>현재 확인 자료를 기준으로 계산한 예상값입니다. 대출 승계, 분담금과 조합 정산에 따라 변경될 수 있습니다.</p></details></section>${consultBlock()}`}
function insightCards(items){return `<div class="insights">${items.map(item=>`<a class="article" href="${item.url}" target="_blank" rel="noopener" aria-label="${item.title} 블로그 원문 새 창"><div class="thumb"></div><small>${item.category}</small><h3>${item.title}</h3><div class="article-meta"><span>${item.date}</span><strong>블로그 원문 ↗</strong></div></a>`).join('')}</div>`}
function insightBlock(){return `<section class="section"><div class="section-head"><div><p class="eyebrow">Kim's Local Analysis</p><h2><a href="#/insights" aria-label="김소장의 분석 카테고리로 이동">김소장의 분석</a></h2></div><a class="text-link" href="#/insights">분석 전체보기 →</a></div>${insightCards(insightArticles.slice(0,3))}</section>`}
function insightsPage(){return `<div class="page-hero insights-hero"><p class="eyebrow">Kim's Local Analysis</p><h1>김소장의 분석</h1><p>현장에서 확인한 매물과 사업 진행상황을 가격 구조, 초기투자금, 총매수가 관점으로 해석합니다.</p></div><section class="section insights-page" style="padding-top:20px"><div class="blog-source-strip"><span><strong>김소장의 콘텐츠 채널</strong> · 블로그 분석과 현장 소식을 확인하세요.</span><div class="source-actions"><a class="text-link" href="https://blog.naver.com/partir_12" target="_blank" rel="noopener">네이버 블로그 ↗</a><a class="text-link" href="https://naver.me/xqbPaWUt" target="_blank" rel="noopener">네이버 클립 ↗</a><a class="text-link instagram-link" href="https://www.instagram.com/naega_find/" target="_blank" rel="noopener">Instagram @naega_find ↗</a></div></div>${insightCards(insightArticles)}</section>${consultBlock()}`}
function consultBlock(){return `<section class="consult"><p class="eyebrow">Current Inventory Request</p><h2>현재 거래 가능한<br>노량진 매물이 궁금하신가요?</h2><p>희망 구역·평형·사용 가능 현금을 알려주시면 현재 기준 거래가능 매물 리스트를 정리해 드립니다.</p><div class="actions" style="justify-content:center"><a class="btn light" href="#/contact">매물 리스트 요청하기</a><a class="btn secondary" style="color:white;border-color:white" href="#/contact">매도 의뢰하기</a></div></section>`}
function search(){return `<div class="page-hero"><p class="eyebrow">Guided Search</p><h1>내 예산으로 찾기</h1><p>복잡한 조건 대신, 실제 필요한 자금부터 선택하세요.</p></div><section class="section search-layout"><aside class="panel"><div class="field"><label>어느 지역을 보고 계세요?</label><select id="region"><option value="">둘 다</option><option>노량진뉴타운</option><option>상도 신속통합기획</option></select></div><div class="field"><label>최대 초기투자금 <b id="initialLabel">25억</b></label><input id="maxInitial" type="range" min="10" max="40" value="25"></div><div class="field"><label>최대 총매수가 <b id="totalLabel">30억</b></label><input id="maxTotal" type="range" min="15" max="50" value="30"></div><div class="field"><label>원하는 평형</label><select id="unit"><option value="">상관없음</option><option value="59">59㎡</option><option value="84">84㎡</option><option value="대형">대형</option></select></div><button class="btn" id="filterBtn">조건에 맞는 매물 보기</button></aside><div><div class="section-head"><div><h2 id="resultCount">조건에 맞는 매물</h2><p class="muted" id="conditions"></p></div></div><div class="results" id="results"></div></div></section>`}
function runFilter(){const region=document.querySelector('#region')?.value||'',mi=(+document.querySelector('#maxInitial')?.value||25)*1e8,mt=(+document.querySelector('#maxTotal')?.value||30)*1e8,unit=document.querySelector('#unit')?.value||'';const list=properties.filter(p=>isPublicListing(p)&&!['sold','hidden'].includes(p.status)&&(!region||p.region===region)&&Number.isFinite(p.initial)&&Number.isFinite(p.total)&&p.initial<=mi&&p.total<=mt&&(!unit||p.unit.includes(unit)));document.querySelector('#results').innerHTML=list.map(card).join('')||'<p>조건에 맞는 공개 매물이 없습니다. 금액 미확정 매물은 구역별 거래현황에서 확인해 주세요.</p>';document.querySelector('#resultCount').textContent=`조건에 맞는 매물 ${list.length}건`;document.querySelector('#conditions').textContent=`초기투자금 ${won(mi)} 이하 · 총매수가 ${won(mt)} 이하${unit?' · '+unit+'㎡':''} · 금액 확인 완료 매물 기준`}
function detail(id){
 const p=properties.find(x=>x.id===id);if(!p||!isPublicListing(p))return notFound();
 const hasRefund=Number(p.refund)>0,ad=advertisingOf(p),missing=advertisingMissing(p),verified=advertisingVerified(p);
 const floorText=hasAdValue(ad.floor)||hasAdValue(ad.totalFloors)?`${adDisplay(ad.floor)} / 총 ${adDisplay(ad.totalFloors)}`:'<span class="ad-missing">확인 필요</span>';
 const directionText=hasAdValue(ad.direction)?`${adDisplay(ad.direction)} <small>(${adDisplay(ad.directionBasis)} 기준)</small>`:'<span class="ad-missing">확인 필요</span>';
 const roomText=hasAdValue(ad.rooms)||hasAdValue(ad.bathrooms)?`방 ${adDisplay(ad.rooms)} · 욕실 ${adDisplay(ad.bathrooms)}`:'<span class="ad-missing">확인 필요</span>';
 const managementText=hasAdValue(ad.managementFee)?`${Number(ad.managementFee)===0?'없음':`${Number(ad.managementFee).toLocaleString('ko-KR')}원/월`}<small>${hasAdValue(ad.managementFeeDetails)?escapeHtml(ad.managementFeeDetails):' · 세부내역 확인 필요'}</small>`:'<span class="ad-missing">확인 필요</span>';
 return `<div class="page-hero"><a class="text-link" href="#/search">← 매물목록</a></div><section class="section detail-top" style="padding-top:0"><div class="detail-image">${propertyImage(p,true)}</div><div class="detail-info"><p class="eyebrow">${p.id} · ${statusText[p.status]}</p><h1>${p.area}<br>${p.unit} 입주권</h1><p class="muted">${p.verificationLabel||`최근 확인 ${p.verified||'-'}`}<br>${p.listedAt?`블로그 등록일 ${p.listedAt}`:''}</p><hr><p>매매가</p><div class="big-number">${won(p.sale)}</div><div class="facts" style="grid-template-columns:1fr 1fr"><div class="fact"><small>초기투자금</small><b>${won(p.initial)}</b></div><div class="fact"><small>총 예상 매수가</small><b>${won(p.total)}</b></div></div>${p.dataNote?`<div class="notice">${p.dataNote}</div>`:''}<div class="actions"><a class="btn" href="#/contact">이 매물 상담하기</a>${p.blogUrl?`<a class="btn secondary" href="${p.blogUrl}" target="_blank" rel="noopener">블로그 원문 ↗</a>`:''}</div></div></section><section class="section"><div class="section-head"><div><h2>가격 상세</h2><p class="muted">내가 찾던 부동산 블로그 게시글 기준</p></div></div><div class="facts price-breakdown ${hasRefund?'has-refund':''}"><div class="fact"><small>매매가</small><b>${won(p.sale)}</b></div><div class="fact"><small>승계가능 대출</small><b>${won(p.loan)}</b></div><div class="fact"><small>예상 분담금</small><b>${won(p.contribution)}</b></div>${hasRefund?`<div class="fact refund-fact"><small>예상 환급금 · 해당 시</small><b>${won(p.refund)}</b></div>`:''}</div>${hasRefund?'<div class="notice refund-notice">예상 환급금은 권리가액보다 조합원분양가가 낮아 환급이 예상되는 경우에만 표시합니다.</div>':'<div class="notice">총 예상 매수가는 매매가에 예상 분담금을 반영한 금액입니다.</div>'}<div class="notice">매물 상태와 예상값은 확인 시점 이후 변경될 수 있습니다. 계약 전 블로그 원문과 최신 조건을 다시 확인해 주세요.</div></section><section class="section ad-disclosure"><div class="section-head"><div><p class="eyebrow">Required Advertising Disclosure</p><h2>중개대상물 표시·광고 정보</h2><p class="muted">관계 장부와 중개의뢰 내용을 기준으로 확인된 값만 표시합니다.</p></div><span class="ad-state ${verified?'verified':'review'}">${verified?'광고정보 확인 완료':'광고정보 검수 중'}</span></div>${verified?'':`<div class="notice ad-review-notice"><strong>현재 공개 정보만으로 광고 필수항목 확인이 끝나지 않았습니다.</strong><br>누락 ${missing.length}개 항목은 관리자 검수 후 확정해야 하며, 계약 전 최신 원자료를 다시 확인합니다.</div>`}<div class="ad-disclosure-grid"><div><small>소재지</small><strong>${adDisplay(ad.location)}</strong></div><div><small>면적</small><strong>${adDisplay(ad.areaSqm,'㎡')}</strong></div><div><small>가격</small><strong>${hasAdValue(p.sale)?won(p.sale):'<span class="ad-missing">확인 필요</span>'}</strong></div><div><small>중개대상물 종류</small><strong>${adDisplay(ad.propertyType)}</strong></div><div><small>거래형태</small><strong>${adDisplay(ad.transactionType)}</strong></div><div><small>해당 층 / 총 층수</small><strong>${floorText}</strong></div><div><small>사용승인·검사일</small><strong>${adDisplay(ad.approvalDate)}</strong></div><div><small>방향</small><strong>${directionText}</strong></div><div><small>방 / 욕실</small><strong>${roomText}</strong></div><div><small>입주가능일</small><strong>${adDisplay(ad.moveInDate)}</strong></div><div><small>주차대수</small><strong>${adDisplay(ad.parking)}</strong></div><div><small>관리비</small><strong>${managementText}</strong></div></div><div class="office-disclosure"><div><p class="eyebrow">Brokerage Office</p><h3>${OFFICE_DISCLOSURE.name}</h3><p>${OFFICE_DISCLOSURE.address}</p></div><dl><div><dt>개업공인중개사</dt><dd>${OFFICE_DISCLOSURE.representative}</dd></div><div><dt>연락처</dt><dd><a href="tel:${OFFICE_DISCLOSURE.phone}">${OFFICE_DISCLOSURE.phone}</a></dd></div><div><dt>중개사무소 등록번호</dt><dd>${OFFICE_DISCLOSURE.registrationNumber}</dd></div></dl></div><p class="ad-source-note">건축물에 해당하는 표시항목까지 포함한 검수표입니다. <a href="https://www.law.go.kr/LSW/lsLinkCommonInfo.do?chrClsCd=010202&lspttninfSeq=106742" target="_blank" rel="noopener">공인중개사법 시행령 제17조의2 ↗</a> · <a href="https://www.law.go.kr/admRulLsInfoP.do?admRulSeq=2100000250356" target="_blank" rel="noopener">국토교통부 세부기준 ↗</a></p></section>${consultBlock()}`
}
function area(type){
 const nory=type==='noryangjin',name=nory?'노량진뉴타운':'상도 신속통합기획';
 const items=properties.filter(p=>isPublicListing(p)&&p.region===name&&!['sold','hidden'].includes(p.status));
 const deals=transactions.filter(t=>t.region===name),cfg=getDataConfig();
 const progressPreview=nory?`<section class="section"><div class="section-head"><div><h2>1~8구역 진행상황</h2><p class="muted">이주·철거·공사 단계별로 현재 위치를 비교합니다.</p></div><a class="btn secondary" href="#/progress">구역별 진행상황 보기</a></div><div class="progress-preview">${progressData.areas.map(item=>`<a href="#/progress"><span class="phase-chip ${item.phaseGroup}">${item.phaseGroup}</span><strong>${item.area}</strong><small>${item.headline}</small></a>`).join('')}</div></section>`:`<section class="section"><h2>사업 진행</h2><div class="facts">${['정비구역','신속통합기획','정비계획','구역지정'].map((step,index)=>`<div class="fact"><small>0${index+1}</small><b>${step}</b></div>`).join('')}</div></section>`;
 return `<section class="hero"><div class="hero-image"><div class="hero-copy"><p class="eyebrow">Area Guide</p><h1>${name}</h1><p>${nory?'내가 찾던 부동산 블로그의 구역별 확인매물과 사업 진행단계를 함께 비교합니다.':'다음 재개발 흐름을 장기투자 관점으로 살펴봅니다.'}</p></div></div></section><section class="section"><div class="facts"><div class="fact"><small>추적 구역</small><b>${nory?'8개':'2개'}</b></div><div class="fact"><small>핵심 단계</small><b>${nory?'이주~본공사':'신속통합기획'}</b></div><div class="fact"><small>현재 공개매물</small><b>${items.length}건</b></div><div class="fact"><small>최근 업데이트</small><b>${nory?propertySyncMeta.asOf:'2026.08.20'}</b></div></div>${nory?`<div class="blog-source-strip"><span><strong>매물 기준 출처</strong> · 내가 찾던 부동산 네이버 블로그</span><div class="source-actions"><a class="text-link" href="#/progress">진행상황 보기 →</a><a class="text-link" href="${cfg.noryangjinBlogUrl}" target="_blank" rel="noopener">블로그 전체보기 ↗</a></div></div>`:''}<div class="section-head"><h2>현재 매물</h2></div>${shelf(items)}</section>${progressPreview}<section class="section"><div class="section-head"><div><h2>${name} 실거래</h2><p class="muted">최근 신고된 거래 데이터입니다.</p></div><a class="text-link" href="#/transactions">전체 실거래 보기 →</a></div>${transactionRows(deals.slice(0,5))}</section>${insightBlock()}`;
}
function contact(){const kakao=getKakaoUrl(),nory=properties.filter(p=>p.region==='노량진뉴타운'&&isPublicListing(p)&&!['sold','hidden'].includes(p.status));return `<div class="page-hero"><p class="eyebrow">Buyer Consultation</p><h1>현재 거래 가능한<br>노량진 매물을 받아보세요.</h1><p>희망 구역과 자금 조건을 정리해 전화 또는 카카오톡으로 바로 상담할 수 있습니다.</p></div><section class="section contact-section"><div class="inventory-offer"><p class="eyebrow">Current Inventory List</p><h2>매수자 요청 시,<br>현재 기준 거래가능 매물 리스트 제공</h2><p>상담 시 희망 구역·평형·사용 가능한 현금을 알려주시면 비교 가능한 노량진 매물을 정리해 드립니다.</p><div class="inventory-offer-grid"><div><small>현재 공개·거래가능</small><strong>${nory.length}건 확인</strong></div><div><small>포함 정보</small><strong>매매가 · 초투 · 총매수가</strong></div><div><small>확인 기준</small><strong>등록일 · 확인 주차</strong></div></div></div><div class="contact-direct"><a href="tel:02-816-5700" data-conversion="phone"><span>☎</span><div><small>바로 전화하기</small><strong>02-816-5700</strong></div></a>${kakao?`<a class="kakao-direct" href="${kakao}" target="_blank" rel="noopener" data-conversion="kakao"><span>💬</span><div><small>오픈채팅 상담</small><strong>카카오톡으로 매물 요청</strong></div></a>`:''}</div><form class="panel contact-form" onsubmit="submitConsultation(event)"><div class="form-intro"><p class="eyebrow">Prepare Your Message</p><h2>상담 내용을 미리 정리하세요.</h2><p>입력 내용은 이 사이트 서버에 저장되지 않습니다. 상담 문구를 복사한 뒤 카카오톡 상담방을 엽니다.</p></div><div class="field"><label>이름</label><input name="name" autocomplete="name" placeholder="성함"></div><div class="field"><label>연락처</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="010-0000-0000"></div><div class="field"><label>상담유형</label><select name="type"><option>현재 거래가능 매물 리스트 요청</option><option>매수 상담</option><option>매도 의뢰</option></select></div><div class="field"><label>관심구역</label><input name="area" placeholder="예: 노량진7구역"></div><div class="field"><label>사용가능 현금</label><input name="budget" placeholder="예: 20억"></div><div class="field"><label>원하는 평형</label><input name="unit" placeholder="예: 59㎡, 84㎡, 1+1"></div><div class="field"><label>추가 문의</label><textarea name="message" rows="4" placeholder="필요한 조건이나 상담 가능한 시간을 남겨주세요."></textarea></div><p class="privacy-mini">사이트 자체에서 개인정보를 수집·저장하지 않습니다. 카카오톡 이동 후 전송되는 정보에는 카카오 서비스 정책이 적용됩니다. <a href="#/privacy">자세히 보기</a></p><div class="actions"><button class="btn kakao" type="submit">상담 내용 복사 후 카카오 열기</button></div></form></section>`}
async function submitConsultation(event){event.preventDefault();const data=new FormData(event.target),lines=['[내가 찾던 부동산 상담 요청]',`상담유형: ${data.get('type')||'-'}`,`이름: ${data.get('name')||'-'}`,`연락처: ${data.get('phone')||'-'}`,`관심구역: ${data.get('area')||'-'}`,`사용가능 현금: ${data.get('budget')||'-'}`,`희망평형: ${data.get('unit')||'-'}`,`문의: ${data.get('message')||'-'}`],message=lines.join('\n');let copied=false;try{await navigator.clipboard.writeText(message);copied=true}catch{}trackConversion('kakao-form');alert(copied?'상담 내용을 복사했습니다. 카카오톡에서 붙여넣어 주세요.':'카카오톡이 열립니다. 입력하신 조건을 대화창에 남겨주세요.');const kakao=getKakaoUrl();if(kakao)window.open(kakao,'_blank','noopener')}
function privacy(){return `<div class="page-hero"><p class="eyebrow">Privacy Notice</p><h1>개인정보 처리 안내</h1><p>현재 웹사이트의 상담 기능과 외부 서비스 연결 방식을 안내합니다.</p></div><section class="section legal-page" style="padding-top:20px"><article><h2>1. 사이트 내 개인정보 처리</h2><p>현재 웹사이트는 별도의 회원가입, 데이터베이스 또는 상담 접수 서버를 운영하지 않습니다. 재개발 정보 검색, 김소장 안내봇과 상담 준비 양식에 입력한 내용은 사이트 서버로 전송하거나 저장하지 않으며, 이용자의 기기에서 검색 결과와 안내 문구를 만드는 데만 사용합니다.</p></article><article><h2>2. 전화·카카오톡 상담</h2><p>전화 연결 시 통신사 서비스가, 카카오톡 오픈채팅으로 이동한 이후에는 카카오의 개인정보 처리방침과 서비스 정책이 적용됩니다. 실제 상담 과정에서 제공한 정보는 상담 및 중개업무 수행을 위해 필요한 범위에서 처리됩니다.</p></article><article><h2>3. 매물 및 이용 기록</h2><p>관리자가 등록한 매물 상태와 연결 설정은 해당 브라우저의 로컬 저장공간에 보관될 수 있습니다. 광고 성과 측정 도구를 추후 설치할 경우 적용 도구, 수집 항목과 보유기간을 이 안내에 추가해야 합니다.</p></article><article><h2>4. 문의처</h2><p>내가찾던부동산 · 대표 김윤아<br>서울특별시 동작구 장승배기로 131, 1층<br>전화 02-816-5700 · 휴대전화 010-7752-9837</p></article><p class="muted">시행일: 2026년 8월 20일</p></section>`}
function chatbotReply(query){const compact=normalizeSearch(query),areaMatch=compact.match(/(?:노량진)?([1-8])구역/);if(areaMatch){const areaName=`노량진${areaMatch[1]}구역`,item=progressData.areas.find(row=>row.area===areaName),live=properties.filter(p=>p.area===areaName&&isPublicListing(p)&&!['sold','hidden'].includes(p.status)).length;return `<strong>${areaName}</strong>${item?`은 현재 <b>${item.phaseGroup}</b> 단계로 정리되어 있습니다. ${item.headline}`:'의 최신 진행상황을 확인해 보세요.'}<br><a href="#/progress">진행상황 보기 →</a> · <a href="#/market-status">현재 매물 ${live}건 보기 →</a>`}if(/프리미엄|피|p$/.test(compact))return `공개 실거래만으로는 입주권 프리미엄을 정확히 분리하기 어렵습니다. 구역별 참고자료는 요청하시면 확인 가능한 범위에서 안내해 드립니다.<br><a href="#/contact">프리미엄 자료 문의 →</a>`;if(/실거래|거래내역|거래가/.test(compact))return `노량진뉴타운과 상도 신속통합기획의 공개 실거래 흐름을 확인할 수 있습니다.<br><a href="#/transactions">실거래내역 보기 →</a>`;if(/매물|초기투자|총매수|예산|평형/.test(compact))return `초기투자금·총 예상 매수가·평형으로 현재 공개매물을 비교할 수 있습니다.<br><a href="#/search">조건으로 매물 찾기 →</a> · <a href="#/market-status">거래가능 현황 →</a>`;if(/상도|신통/.test(compact))return `상도14·15구역의 신속통합기획 정보와 실거래를 확인할 수 있습니다.<br><a href="#/area/sangdo">상도 구역정보 →</a>`;if(/김소장|분석|블로그/.test(compact))return `김소장이 현장에서 정리한 구역·매물·시장 분석글을 모아두었습니다.<br><a href="#/insights">김소장의 분석 보기 →</a>`;return `원하는 정보를 바로 찾지 못했습니다. ‘노량진7구역’, ‘현재 매물’, ‘실거래’, ‘프리미엄’처럼 입력해 보세요.<br><a href="#/areas">재개발 구역별 정보 →</a> · <a href="#/contact">김소장에게 문의 →</a>`}
function appendChatMessage(role,content){const target=document.querySelector('#chatMessages');if(!target)return;target.insertAdjacentHTML('beforeend',`<div class="chat-message ${role}"><p>${content}</p></div>`);target.scrollTop=target.scrollHeight}
function sendChatbotQuery(query){const value=String(query||'').trim();if(!value)return;appendChatMessage('user',escapeHtml(value));appendChatMessage('bot',chatbotReply(value))}
function submitChatbot(event){event.preventDefault();const field=document.querySelector('#chatbotInput'),value=field?.value||'';if(field)field.value='';sendChatbotQuery(value)}
function toggleChatbot(force){const panel=document.querySelector('#chatbotPanel'),button=document.querySelector('#chatbotToggle');if(!panel||!button)return;const open=typeof force==='boolean'?force:!panel.classList.contains('open');panel.classList[open?'add':'remove']('open');panel.setAttribute('aria-hidden',String(!open));button.setAttribute('aria-expanded',String(open));if(open)document.querySelector('#chatbotInput')?.focus?.()}
function adminAdvertisingFields(){return `<div class="wide admin-ad-heading"><p class="eyebrow">Advertising Checklist</p><h3>중개대상물 표시·광고 정보</h3><p class="muted">공개 전 관계 장부와 중개의뢰 내용을 대조해 입력하세요. 미래 신축 평형은 현재 중개대상물의 법정 면적을 대신하지 않습니다.</p></div><div class="field wide"><label>대표 이미지 URL</label><input name="imageUrl" type="url" placeholder="https://... 또는 블로그 대표 이미지 URL"></div><div class="field wide"><label>소재지</label><input name="adLocation" placeholder="건축물대장·토지대장 기준 소재지"></div><div class="field"><label>중개대상물 종류</label><input name="adPropertyType" value="재개발 조합원입주권"></div><div class="field"><label>거래형태</label><select name="adTransactionType"><option>매매</option><option>임대차</option><option>교환</option><option>그 밖의 권리 득실변경</option></select></div><div class="field"><label>면적 (㎡)</label><input name="adAreaSqm" type="number" step="0.01" min="0"></div><div class="field"><label>해당 층 / 총 층수</label><span class="inline-fields"><input name="adFloor" placeholder="예: 3층"><input name="adTotalFloors" placeholder="예: 총 4층"></span></div><div class="field"><label>사용승인·검사일</label><input name="adApprovalDate" type="date"></div><div class="field"><label>방향 및 기준</label><span class="inline-fields"><select name="adDirection"><option value="">선택</option><option>남향</option><option>남동향</option><option>남서향</option><option>동향</option><option>서향</option><option>북향</option><option>북동향</option><option>북서향</option></select><select name="adDirectionBasis"><option value="">기준 선택</option><option>거실</option><option>안방</option><option>주출입구</option></select></span></div><div class="field"><label>방 수 / 욕실 수</label><span class="inline-fields"><input name="adRooms" type="number" min="0" placeholder="방"><input name="adBathrooms" type="number" min="0" placeholder="욕실"></span></div><div class="field"><label>입주가능일</label><input name="adMoveInDate" placeholder="예: 2026-10-01 또는 협의 가능"></div><div class="field"><label>총 주차대수</label><input name="adParking" placeholder="예: 총 2대"></div><div class="field"><label>월 관리비 (원)</label><input name="adManagementFee" type="number" min="0" placeholder="없으면 0"></div><div class="field wide"><label>관리비 포함 비목·세부내역</label><input name="adManagementFeeDetails" placeholder="예: 일반관리비 50,000원 · 수도료 실비"></div><div class="field wide ad-confirm"><label><input name="adVerified" type="checkbox"> 관계 장부와 중개의뢰 내용 대조를 마쳤으며 광고정보 검수 완료로 저장합니다.</label><small class="muted">체크하더라도 필수항목이 비어 있으면 공개 저장되지 않습니다.</small></div>`}
function addPropertyWithAdvertising(e){
 e.preventDefault();const d=new FormData(e.target),sale=+d.get('sale')*1e8,loan=+d.get('loan')*1e8,contribution=+d.get('contribution')*1e8,refund=+d.get('refund')*1e8,today=new Date(),listedAt=today.toISOString().slice(0,10),week=Math.ceil(today.getDate()/7),verificationLabel=`${today.getFullYear()}년 ${today.getMonth()+1}월 ${week}주차 확인매물`;
 const num=name=>d.get(name)===''?null:Number(d.get(name)),advertising={reviewStatus:d.get('adVerified')?'verified':'needs_review',propertyType:d.get('adPropertyType')||'',transactionType:d.get('adTransactionType')||'',location:d.get('adLocation')||'',areaSqm:num('adAreaSqm'),floor:d.get('adFloor')||'',totalFloors:d.get('adTotalFloors')||'',approvalDate:d.get('adApprovalDate')||'',direction:d.get('adDirection')||'',directionBasis:d.get('adDirectionBasis')||'',rooms:num('adRooms'),bathrooms:num('adBathrooms'),moveInDate:d.get('adMoveInDate')||'',parking:d.get('adParking')||'',managementFee:num('adManagementFee'),managementFeeDetails:d.get('adManagementFeeDetails')||''};
 const draft={id:d.get('id'),region:d.get('region'),area:d.get('area'),unit:d.get('unit'),sale,loan,contribution,refund,initial:sale-loan,total:sale+contribution-refund,status:d.get('status')||'available',inventory:'owned',featured:!!d.get('featured'),public:false,blogUrl:d.get('blogUrl')||'',imageUrl:d.get('imageUrl')||'',imageAlt:`${d.get('area')} ${d.get('unit')} 입주권 대표 이미지`,listedAt,verified:listedAt.replaceAll('-','.'),verificationLabel,source:d.get('blogUrl')?'네이버 블로그':'관리자 직접등록',advertising};
 const wantsPublic=!!d.get('public'),missing=advertisingMissing(draft);if(advertising.reviewStatus==='verified'&&missing.length){alert(`광고정보 검수를 완료하려면 다음 항목을 입력해 주세요.\n${missing.join(', ')}`);return}draft.public=wantsPublic&&advertising.reviewStatus==='verified';properties.unshift(draft);save();alert(`${draft.public?'공개':'비공개 검수 대기'} 상태로 등록되었습니다. 초기투자금 ${won(sale-loan)}, 총 예상 매수가 ${won(sale+contribution-refund)}`);route()
}
function admin(){const cfg=getDataConfig();return `<div class="page-hero"><p class="eyebrow">Management Console</p><h1>매물과 데이터 관리</h1></div><section class="admin-shell"><nav class="admin-nav"><b>Dashboard</b><a href="#admin-property">매물관리</a><a href="#admin-settings">연결 설정</a><a href="#/market-status">거래현황 보기</a><a href="#/transactions">실거래 보기</a><a href="#/">고객 화면</a></nav><div class="admin-main"><div class="notice">블로그에 등록한 매물의 URL과 거래상태를 관리합니다. 거래완료로 변경하면 고객 검색에서는 제외되고 거래완료 아카이브로 이동합니다.</div><h2 id="admin-property">새 매물 등록</h2><form id="adminForm" class="panel admin-form"><div class="field"><label>매물번호</label><input name="id" required placeholder="N2-84A-001"></div><div class="field"><label>권역</label><select name="region"><option>노량진뉴타운</option><option>상도 신속통합기획</option></select></div><div class="field"><label>구역</label><input name="area" required placeholder="노량진2구역"></div><div class="field"><label>평형</label><input name="unit" required placeholder="84A"></div><div class="field"><label>매매가 (억원)</label><input name="sale" type="number" step=".01" required></div><div class="field"><label>승계가능 대출 (억원)</label><input name="loan" type="number" step=".01" value="0"></div><div class="field"><label>예상 분담금 (억원)</label><input name="contribution" type="number" step=".01" value="0"></div><div class="field"><label>예상 환급금 (해당하는 경우만)</label><input name="refund" type="number" step=".01" value="0"><small class="muted">권리가액보다 조합원분양가가 낮아 환급이 예상될 때만 입력합니다.</small></div><div class="field wide"><label>네이버 블로그 매물 URL</label><input name="blogUrl" type="url" placeholder="https://blog.naver.com/..."></div><div class="field"><label>거래상태</label><select name="status">${Object.entries(statusText).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div><div class="field"><label>노출 설정</label><span><input name="featured" type="checkbox"> 추천매물 &nbsp; <input name="public" type="checkbox" checked> 공개</span></div><div class="wide"><button class="btn">자동계산 후 등록</button></div></form><h2 style="margin-top:50px">등록 매물 ${properties.length}건</h2><div style="overflow:auto"><table class="transaction-table"><thead><tr><th>번호</th><th>구역·평형</th><th>매매가</th><th>블로그</th><th>상태 변경</th></tr></thead><tbody>${properties.map(p=>`<tr><td>${p.id}</td><td>${p.area} · ${p.unit}</td><td>${won(p.sale)}</td><td>${p.blogUrl?`<a class="text-link" href="${p.blogUrl}" target="_blank">원문 ↗</a>`:'미등록'}</td><td><select class="admin-status" onchange="setPropertyStatus('${p.id}',this.value)">${Object.entries(statusText).map(([v,t])=>`<option value="${v}" ${p.status===v?'selected':''}>${t}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><h2 id="admin-settings" style="margin-top:70px">외부 서비스 연결</h2><p class="muted">카카오톡 상담과 GitHub 실거래 데이터 주소를 한 곳에서 관리합니다.</p><form id="syncForm" class="panel admin-form"><div class="field wide"><label>카카오톡 채널 채팅 URL 또는 공개 ID</label><input name="kakaoChatUrl" value="${cfg.kakaoChatUrl||''}" placeholder="예: https://pf.kakao.com/_채널ID/chat 또는 _채널ID"></div><div class="field wide"><label>노량진뉴타운 JSON Raw URL</label><input name="noryangjinUrl" type="url" value="${cfg.noryangjinTransactionsUrl||''}" placeholder="https://raw.githubusercontent.com/.../noryangjin.json"></div><div class="field wide"><label>상도 신속통합기획 JSON Raw URL</label><input name="sangdoUrl" type="url" value="${cfg.sangdoTransactionsUrl||''}" placeholder="https://raw.githubusercontent.com/.../sangdo.json"></div><div class="wide"><button class="btn">연결 설정 저장</button></div></form></div></section>`}
function setPropertyStatus(id,status){const p=properties.find(x=>x.id===id);if(!p)return;p.status=status;p.manualStatus=true;if(status==='sold')p.soldAt=new Date().toISOString().slice(0,10);save();route()}
function saveSyncConfig(e){e.preventDefault();const d=new FormData(e.target);localStorage.setItem('dataConfig',JSON.stringify({kakaoChatUrl:normalizeKakaoUrl(d.get('kakaoChatUrl')),noryangjinTransactionsUrl:d.get('noryangjinUrl'),sangdoTransactionsUrl:d.get('sangdoUrl'),refreshMinutes:30}));alert('카카오톡과 실거래 데이터 연결 설정을 저장했습니다.');route()}
function notFound(){return `<div class="page-hero"><h1>페이지를 찾을 수 없습니다.</h1><a class="btn" href="#/">홈으로</a></div>`}
function route(){
 const params=new URLSearchParams(location.search||''),path=location.hash.slice(2)||(params.get('utm_source')==='naver'?'landing':'');
 let html;
 if(!path)html=home();
 else if(path==='landing')html=landing();
 else if(path==='areas')html=areasPage();
 else if(path==='search')html=search();
 else if(path==='market-status'||path.startsWith('market-status/'))html=marketStatus();
 else if(path==='progress')html=progressPage();
 else if(path==='transactions')html=transactionsPage();
 else if(path.startsWith('property/'))html=detail(path.split('/')[1]);
 else if(path==='area/noryangjin')html=area('noryangjin');
 else if(path==='area/sangdo')html=area('sangdo');
 else if(path==='contact')html=contact();
 else if(path==='privacy')html=privacy();
 else if(path==='admin')html=admin();
 else if(path==='insights')html=insightsPage();
 else html=notFound();
 document.querySelector('#app').innerHTML=html;
 window.scrollTo(0,0);
 if(!path){
  const searchForm=document.querySelector('#homeSearchForm');if(searchForm)searchForm.onsubmit=runHomeSearch;
  document.querySelectorAll('[data-home-query]').forEach(button=>button.onclick=()=>runHomeSearch(button.dataset.homeQuery));
 }
 if(path==='search'){
  runFilter();
  ['region','unit'].forEach(id=>document.querySelector('#'+id).onchange=runFilter);
  ['maxInitial','maxTotal'].forEach(id=>document.querySelector('#'+id).oninput=e=>{document.querySelector('#'+(id==='maxInitial'?'initialLabel':'totalLabel')).textContent=e.target.value+'억';runFilter()});
  document.querySelector('#filterBtn').onclick=runFilter;
 }
 if(path==='progress'){
  document.querySelectorAll('[data-progress-group]').forEach(btn=>btn.onclick=()=>{
   document.querySelectorAll('[data-progress-group]').forEach(item=>item.classList.remove('active'));
   btn.classList.add('active');
   renderProgressFilter(btn.dataset.progressGroup);
  });
 }
 if(path==='transactions'){
  document.querySelectorAll('.market-tabs button').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('.market-tabs button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');renderTransactionFilter(btn.dataset.region)});
  loadRemoteTransactions().then(result=>{const state=document.querySelector('#syncState');if(state)state.innerHTML=`<span class="data-source">${result.message}</span>`;renderTransactionFilter(document.querySelector('.market-tabs .active')?.dataset.region||'')});
 }
 if(path==='admin'){
  const adminForm=document.querySelector('#adminForm');
  adminForm.querySelector('.wide:last-child').insertAdjacentHTML('beforebegin',adminAdvertisingFields());
  adminForm.onsubmit=addPropertyWithAdvertising;
  document.querySelector('#syncForm').onsubmit=saveSyncConfig;
 }
}
function addProperty(e){e.preventDefault();const d=new FormData(e.target),sale=+d.get('sale')*1e8,loan=+d.get('loan')*1e8,contribution=+d.get('contribution')*1e8,refund=+d.get('refund')*1e8,today=new Date(),listedAt=today.toISOString().slice(0,10),week=Math.ceil(today.getDate()/7),verificationLabel=`${today.getFullYear()}년 ${today.getMonth()+1}월 ${week}주차 확인매물`;properties.unshift({id:d.get('id'),region:d.get('region'),area:d.get('area'),unit:d.get('unit'),sale,loan,contribution,refund,initial:sale-loan,total:sale+contribution-refund,status:d.get('status')||'available',inventory:'owned',featured:!!d.get('featured'),public:!!d.get('public'),blogUrl:d.get('blogUrl')||'',listedAt,verified:listedAt.replaceAll('-','.'),verificationLabel,source:d.get('blogUrl')?'네이버 블로그':'관리자 직접등록'});save();alert(`등록되었습니다. 초기투자금 ${won(sale-loan)}, 총 예상 매수가 ${won(sale+contribution-refund)}`);route()}
function trackConversion(type){window.dataLayer=window.dataLayer||[];window.dataLayer.push({event:'consultation_click',conversionType:type,path:location.hash||location.pathname});try{window.dispatchEvent(new CustomEvent('consultation-click',{detail:{type}}))}catch{}}
document.addEventListener('click',event=>{const conversion=event.target.closest('[data-conversion]');if(conversion)trackConversion(conversion.dataset.conversion);const link=event.target.closest('a[href="#/contact"]');const kakao=getKakaoUrl();if(link&&kakao){event.preventDefault();trackConversion('kakao-route');window.open(kakao,'_blank','noopener')}});
document.querySelector('#menuBtn').onclick=()=>{document.querySelector('#mobileMenu').classList.add('open');document.querySelector('#mobileMenu').setAttribute('aria-hidden','false')};document.querySelector('#closeMenu').onclick=()=>document.querySelector('#mobileMenu').classList.remove('open');document.querySelector('#mobileMenu').onclick=e=>{if(e.target.tagName==='A')document.querySelector('#mobileMenu').classList.remove('open')};document.querySelector('#searchBtn').onclick=()=>location.hash='#/search';document.querySelector('#chatbotToggle').onclick=()=>toggleChatbot();document.querySelector('#chatbotClose').onclick=()=>toggleChatbot(false);document.querySelector('#chatbotForm').onsubmit=submitChatbot;document.querySelectorAll('[data-chat-query]').forEach(button=>button.onclick=()=>sendChatbotQuery(button.dataset.chatQuery));document.querySelector('#chatbotPanel').onclick=event=>{if(event.target.closest('a[href^="#/"]'))toggleChatbot(false)};document.addEventListener('keydown',event=>{if(event.key==='Escape')toggleChatbot(false)});window.addEventListener('hashchange',route);Promise.all([loadBundledProperties(),loadBundledProgress(),loadBundledTransactions()]).finally(route);
